<template>
  <header class="project-page-header">
    <slot />
    <div class="project-provenance">
      <div class="project-affiliation">
        <ProjectAffiliation v-if="project?.affiliation" :affiliation="project.affiliation" />
        <span v-if="context">{{ context }}</span>
      </div>
      <span class="project-period">{{ period }}</span>
    </div>
  </header>
</template>

<script>
import { projectById } from '../../data/projects';
import ProjectAffiliation from './ProjectAffiliation.vue';

export default {
  name: 'ProjectPageHeader',
  components: { ProjectAffiliation },
  props: {
    projectId: { type: String, required: true },
    context: { type: String, default: '' },
  },
  computed: {
    project() { return projectById(this.projectId); },
    period() {
      const value = this.project?.period || '';
      const range = value.match(/^(\w+) (\d{4})\s*[-–]\s*(\w+) (\d{4})$/);
      if (range && range[2] === range[4]) return `${range[1]} to ${range[3]} ${range[4]}`;
      return value.replace(/\s+[-–]\s+/, ' to ').replace(/Present$/, 'present');
    },
  },
};
</script>

<style scoped>
.project-affiliation-mark { display: block; margin-bottom: 0.35rem; }
</style>
