<template>
  <div class="work-page">
    <h1 data-scroll-reveal>Roles I've Had</h1>
    <article data-scroll-group data-scroll-step="110">
      <p>I have worked in university research labs, AI consulting, and digital transformation.</p>
      <ChapterRail :items="chapterItems" label="Work sections" />
      <div id="timeline" data-scroll-group data-scroll-step="140">
        <div data-scroll-group data-scroll-step="160">
          <section v-for="role in roles" :key="role.id" :id="`work-${role.year}`" class="year" data-scroll-group data-scroll-step="170">
            <h3>{{ role.year }}</h3>
            <section :id="role.anchor" :class="{ 'timeline-portrait-entry': rolePortraits[role.id] }">
              <h4>{{ role.period }}</h4>
              <ul>
                <li class="image-wrapper work-logo"><img :src="role.media" :alt="role.organisation" :style="{ height: role.logoHeight }" /></li>
                <li class="title">{{ role.title }}</li>
                <li class="role">{{ role.organisation }}</li>
                <li class="location">{{ role.location }}</li>
                <li class="work-summary">
                  {{ role.summary }}
                  <span v-if="rolePortraits[role.id]" class="timeline-portrait" aria-hidden="true">
                    <img :src="rolePortraits[role.id]" alt="" :loading="role.id === 'pwc' ? 'eager' : 'lazy'" decoding="async" />
                  </span>
                </li>
                <li class="work-detail-area">
                  <button type="button" class="work-disclosure" :aria-expanded="!!openRoles[role.id]" :aria-controls="`${role.anchor}-details`" @click="toggleRole(role.id, $event)">
                    <span>{{ openRoles[role.id] ? 'Less detail' : 'Work details' }}</span>
                    <svg viewBox="0 0 16 16" aria-hidden="true"><path d="M3 8h10" /><path class="work-plus" d="M8 3v10" /></svg>
                  </button>
                  <div :id="`${role.anchor}-details`" class="work-detail-panel" :class="{ 'is-open': openRoles[role.id], 'is-instant': instantRole === role.id }" :inert="!openRoles[role.id]" :aria-hidden="!openRoles[role.id]">
                    <div class="work-detail-content" :class="{ 'has-categories': role.detailGroups.length > 1 }">
                      <div v-if="role.detailGroups.length > 1" class="work-category-tabs" role="tablist" aria-label="Work categories" @keydown="onCategoryKey($event, role)">
                        <button
                          v-for="group in role.detailGroups"
                          :id="`${role.anchor}-tab-${group.id}`"
                          :key="group.id"
                          type="button"
                          role="tab"
                          :aria-selected="selectedGroup(role) === group.id"
                          :tabindex="selectedGroup(role) === group.id ? 0 : -1"
                          :aria-controls="`${role.anchor}-group-${group.id}`"
                          @click="activeGroups[role.id] = group.id"
                        >{{ group.title }}</button>
                      </div>
                      <div
                        v-for="group in role.detailGroups"
                        v-show="!group.id || selectedGroup(role) === group.id"
                        :id="group.id ? `${role.anchor}-group-${group.id}` : null"
                        :key="group.id || role.id"
                        class="work-detail-group"
                        :class="{ 'is-categorised': group.id }"
                        :role="group.id ? 'tabpanel' : null"
                        :aria-labelledby="group.id ? `${role.anchor}-tab-${group.id}` : null"
                        :tabindex="group.id ? 0 : null"
                      >
                        <div v-for="detail in group.details" :key="detail.title" class="work-detail">
                          <h5 class="work-detail-title">
                            <router-link v-if="detail.route" :to="detail.route" @click.capture="rememberWorkDetails">{{ detail.title }}<ArrowUpRightIcon /></router-link>
                            <a v-else-if="detail.href" :href="detail.href" target="_blank" rel="noopener noreferrer">{{ detail.title }}<ArrowUpRightIcon /></a>
                            <span v-else>{{ detail.title }}</span>
                          </h5>
                          <p>{{ detail.body }}</p>
                        </div>
                      </div>
                    </div>
                  </div>
                </li>
                <li class="work-view-links"><SourceViewLinks :source-id="`experience:${role.id}`" /></li>
              </ul>
            </section>
          </section>
        </div>
      </div>
    </article>
  </div>
</template>
<script>
import scrollRevealMixin from '../mixins/scrollRevealMixin';
import ChapterRail from './ChapterRail.vue';
import SourceViewLinks from './ui/SourceViewLinks.vue';
import { experienceEntries } from '../data/experienceEntries';
import { settleScrollToId } from '../utils/anchorLanding';
import { getWorkDetailsState } from '../utils/routeScroll';

const rolePortraits = {
  pwc: '/assets/img/work/pwc-landmark-street-corner.webp',
  slr: '/assets/img/study/hku-main-building.webp',
  hsbc: '/assets/img/work/hsbc-statue-square-streetscape.webp',
  kiwiview: '/assets/img/work/napier-soundshell.webp',
};

export default {
  name: 'ExperienceTab',
  components: { ChapterRail, SourceViewLinks },
  mixins: [scrollRevealMixin],
  data() {
    const details = getWorkDetailsState(this.$route.fullPath);
    return {
      roles: experienceEntries, rolePortraits,
      openRoles: Object.fromEntries((details?.openRoles || []).map(id => [id, true])),
      activeGroups: { ...details?.activeGroups },
      scrollRevealEnabled: !details, instantRole: '',
      chapterItems: [{ id: 'work-pwc', label: 'PwC' }, { id: 'work-slr', label: 'SLR' }, { id: 'work-hsbc', label: 'HSBC' }, { id: 'work-kiwiview', label: 'Kiwiview' }],
    };
  },
  mounted() { this.scrollToRouteHash(); },
  watch: { '$route.hash'() { this.scrollToRouteHash(); } },
  methods: {
    selectedGroup(role) {
      const saved = this.activeGroups[role.id];
      return role.detailGroups.find(group => group.id === saved)?.id ?? role.detailGroups[0].id;
    },
    onCategoryKey(event, role) {
      if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End'].includes(event.key)) return;
      event.preventDefault();
      const groups = role.detailGroups;
      const current = groups.findIndex(group => group.id === this.selectedGroup(role));
      let next;
      if (event.key === 'Home') next = 0;
      else if (event.key === 'End') next = groups.length - 1;
      else {
        const forward = event.key === 'ArrowRight' || event.key === 'ArrowDown';
        next = (current + (forward ? 1 : -1) + groups.length) % groups.length;
      }
      this.activeGroups[role.id] = groups[next].id;
      event.currentTarget.children[next]?.focus({ preventScroll: true });
    },
    rememberWorkDetails(event) {
      if (event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
      const { history } = window;
      const workDetails = {
        route: this.$route.fullPath,
        openRoles: Object.keys(this.openRoles).filter(id => this.openRoles[id]),
        activeGroups: { ...this.activeGroups },
      };
      history.replaceState({ ...history.state, workDetails }, '');
    },
    toggleRole(id, event) {
      this.instantRole = event.detail === 0 ? id : '';
      this.openRoles[id] = !this.openRoles[id];
    },
    scrollToRouteHash(attempt = 0) {
      if (this.$route.path !== '/experience' || getWorkDetailsState(this.$route.fullPath)) return;
      const hash = this.$route.hash;
      if (!hash) return;
      let id = hash.replace(/^#/, '');
      try { id = decodeURIComponent(id); } catch { /* Keep a plain anchor. */ }
      const role = this.roles.find((entry) => entry.anchor === id);
      if (role) { this.instantRole = role.id; this.openRoles[role.id] = true; }
      this.$nextTick(() => {
        if (settleScrollToId(id)) return;
        if (attempt < 20) window.setTimeout(() => this.scrollToRouteHash(attempt + 1), 80);
      });
    },
  },
};
</script>
